package cn.qingyue.pdf;

import java.io.*;
import java.util.*;

public final class ReaderModuleTest {
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static void invalid(byte[] bytes)throws Exception{try{ReaderDocument.read(new ByteArrayInputStream(bytes));throw new AssertionError("invalid reader data accepted");}catch(IOException expected){}}
    public static void main(String[] args)throws Exception {
        File root=new File(System.getProperty("reader.test.root"));check(root.mkdirs()||root.isDirectory(),"test root");
        ReaderDocument document=new ReaderDocument();ReaderDocument.Bookmark bookmark=document.addBookmark(8,"定理 3");document.addMarkup(8,0xfff6c343,"随机变量",Arrays.asList(new ReaderDocument.Box(.1f,.2f,.3f,.24f),new ReaderDocument.Box(.32f,.2f,.5f,.24f)));
        ReaderDocument.TextBox original=document.addTextBox(8,"Hello 世界\n第二行",0xff123456,.12f,.33f,.026f);
        ByteArrayOutputStream encoded=new ByteArrayOutputStream();document.write(encoded);ReaderDocument decoded=ReaderDocument.read(new ByteArrayInputStream(encoded.toByteArray()));check(decoded.bookmarks().size()==1&&decoded.markups(8).size()==1&&decoded.textBoxes(8).size()==1&&decoded.textBoxes(8).get(0).text.equals("Hello 世界\n第二行"),"reader round trip");
        document.updateTextBox(original,"修改\nline 2",0xffabcdef,.2f,.4f,.03f);check(document.textBoxes(8).get(0).id.equals(original.id)&&Math.abs(document.textBoxes(8).get(0).x-.2f)<.0001f,"text edit/position");
        List<ReaderDocument.TextBox> textUndo=document.textBoxes();document.remove(original.id);document.addBookmark(9,"later bookmark");document.replaceTextBoxes(textUndo);check(document.textBoxes(8).size()==1&&document.bookmarked(9),"text undo erased later bookmark");
        ByteArrayOutputStream legacyBytes=new ByteArrayOutputStream();DataOutputStream legacy=new DataOutputStream(legacyBytes);legacy.writeInt(0x51524452);legacy.writeInt(1);legacy.writeInt(0);legacy.writeInt(0);legacy.flush();check(ReaderDocument.read(new ByteArrayInputStream(legacyBytes.toByteArray())).textBoxes().isEmpty(),"v1 metadata compatibility");
        ReaderDocument snapshot=document.copy();document.remove(bookmark.id);check(snapshot.bookmarked(8)&&!document.bookmarked(8),"snapshot shares mutable lists");
        byte[] trailing=Arrays.copyOf(encoded.toByteArray(),encoded.size()+1);invalid(trailing);invalid(new byte[0]);
        ReaderStore.save(root,"doc-1",snapshot);check(ReaderStore.load(root,"doc-1").bookmarked(8),"reader store round trip");check(ReaderStore.load(root,"missing").bookmarks().isEmpty(),"missing sidecar not empty");try{ReaderStore.file(root,"../escape");throw new AssertionError("unsafe id accepted");}catch(IllegalArgumentException expected){}
        ReaderDocument names=new ReaderDocument();ReaderDocument.Bookmark first=names.addBookmark(23,"  第三章\n重点\u0000  "),second=names.addBookmark(2,"第二页");
        check(first.label.equals("第三章 重点"),"bookmark control characters were not normalized");
        check(names.renameBookmark(first.id,"  定理与例题  "),"rename failed");ReaderDocument.Bookmark renamed=names.bookmarks().get(0);
        check(renamed.id.equals(first.id)&&renamed.page==23&&renamed.createdAt==first.createdAt&&renamed.label.equals("定理与例题"),"rename changed bookmark destination or identity");
        check(names.bookmarks().get(1).id.equals(second.id)&&names.bookmarks().get(1).page==2,"bookmark ordinal confused with PDF page");
        ReaderStore.save(root,"named",names);ReaderDocument savedNames=ReaderStore.load(root,"named");check(savedNames.bookmarks().get(0).page==23&&savedNames.bookmarks().get(0).label.equals("定理与例题"),"named bookmark lost after reopen");
        ByteArrayOutputStream backupNames=new ByteArrayOutputStream();names.write(backupNames);ReaderDocument restoredNames=ReaderDocument.read(new ByteArrayInputStream(backupNames.toByteArray()));check(restoredNames.bookmarks().get(1).id.equals(second.id)&&restoredNames.bookmarks().get(1).page==2,"restore changed bookmark page");
        names.remove(first.id);check(names.bookmarks().get(0).page==2&&!names.renameBookmark(first.id,"已删除"),"deleted bookmark identity retargeted another row");
        try{names.addBookmark(0," \n\u0000\t ");throw new AssertionError("blank name accepted");}catch(IllegalArgumentException expected){}
        String longName=String.join("",Collections.nCopies(121,"🙂"));String safeBookmark=ReaderDocument.bookmarkName(longName);check(safeBookmark.length()==240&&!Character.isHighSurrogate(safeBookmark.charAt(239)),"bookmark clipping split emoji");
        ByteArrayOutputStream oldNamedBytes=new ByteArrayOutputStream();DataOutputStream oldNamed=new DataOutputStream(oldNamedBytes);oldNamed.writeInt(0x51524452);oldNamed.writeInt(1);oldNamed.writeInt(1);byte[] oldId="legacy-bookmark".getBytes("UTF-8"),oldLabel="旧版自定义书签".getBytes("UTF-8");oldNamed.writeInt(oldId.length);oldNamed.write(oldId);oldNamed.writeInt(17);oldNamed.writeInt(oldLabel.length);oldNamed.write(oldLabel);oldNamed.writeLong(1234);oldNamed.writeInt(0);oldNamed.flush();
        ReaderDocument legacyNamed=ReaderDocument.read(new ByteArrayInputStream(oldNamedBytes.toByteArray()));check(legacyNamed.bookmarks().get(0).page==17&&legacyNamed.bookmarks().get(0).label.equals("旧版自定义书签"),"v1 named bookmark target changed");check(legacyNamed.renameBookmark("legacy-bookmark","新版名称")&&legacyNamed.bookmarks().get(0).page==17,"legacy bookmark rename lost target");
        ReaderDocument queuedA=snapshot.copy();queuedA.addBookmark(10,"旧实例待写");long oldRevision=ReaderStore.stage(root,"handoff",queuedA);ReaderDocument reopened=ReaderStore.load(root,"handoff");check(reopened.bookmarked(10),"new instance did not see queued snapshot");reopened.addBookmark(11,"新实例编辑");long newRevision=ReaderStore.stage(root,"handoff",reopened);ReaderStore.saveStaged(root,"handoff",oldRevision);check(ReaderStore.hasPending(root,"handoff"),"old revision cleared newer pending state");ReaderStore.saveStaged(root,"handoff",newRevision);ReaderDocument handedOff=ReaderStore.load(root,"handoff");check(handedOff.bookmarked(10)&&handedOff.bookmarked(11)&&!ReaderStore.hasPending(root,"handoff"),"cross-instance revision handoff lost edits");
        ReaderDocument diskState=new ReaderDocument();diskState.addBookmark(20,"磁盘旧状态");ReaderStore.save(root,"load-race",diskState);ReaderStore.Loaded staleLoad=ReaderStore.loadVersioned(root,"load-race");ReaderDocument newerState=staleLoad.document.copy();newerState.addBookmark(21,"另一实例新状态");long winningRevision=ReaderStore.stageIfCurrent(root,"load-race",newerState,staleLoad.revision);check(winningRevision>=0,"新实例无法基于当前修订暂存");final boolean[] stalePublished={false};check(!ReaderStore.runIfCurrent(root,"load-race",staleLoad.revision,()->stalePublished[0]=true)&&!stalePublished[0],"返回较早的异步加载仍发布了旧状态");ReaderDocument staleEdit=staleLoad.document.copy();staleEdit.addBookmark(22,"旧实例编辑");check(ReaderStore.stageIfCurrent(root,"load-race",staleEdit,staleLoad.revision)<0,"基于旧加载的编辑覆盖了新状态");ReaderStore.saveStaged(root,"load-race",winningRevision);ReaderDocument raceWinner=ReaderStore.load(root,"load-race");check(raceWinner.bookmarked(20)&&raceWinner.bookmarked(21)&&!raceWinner.bookmarked(22),"异步加载竞态丢失了新状态");
        ReaderSourceLink source=ReaderSourceLink.selection("doc-1","概率论",8,"随机变量",snapshot.markups(8).get(0).boxes);ReaderSourceLink parsed=ReaderSourceLink.parse(source.toUri());check(parsed.page==8&&parsed.documentName.equals("概率论")&&parsed.quote.equals("随机变量")&&Math.abs(parsed.x-.1f)<.0001f,"source link round trip");try{ReaderSourceLink.parse("https://invalid");throw new AssertionError("foreign source link accepted");}catch(IllegalArgumentException expected){}
        String emoji=String.join("",Collections.nCopies(3000,"🙂"));ReaderSourceLink clipped=new ReaderSourceLink("doc-1",emoji,0,0,0,emoji);check(!Character.isHighSurrogate(clipped.documentName.charAt(clipped.documentName.length()-1))&&!Character.isHighSurrogate(clipped.quote.charAt(clipped.quote.length()-1)),"source truncation split a surrogate pair");
        try{ReaderSourceLink.parse("qingyue://source?doc=a&doc=b&page=0&x=0&y=0&quote=");throw new AssertionError("duplicate field accepted");}catch(IllegalArgumentException expected){}try{ReaderSourceLink.parse("qingyue://source?v=2&doc=a&page=0&x=0&y=0&quote=");throw new AssertionError("future version accepted");}catch(IllegalArgumentException expected){}
        PageLayout layout=new PageLayout(new float[]{1,1,1});double oldTop=layout.top(2);PageLayout calibrated=layout.withHeight(0,2);check(calibrated.height(0)==2&&calibrated.top(2)>oldTop,"page calibration did not shift following pages");
        List<PdfRenderPlan.Tile> tiles=PdfRenderPlan.visible(3,2048,1.5f,.2f,.3f,.4f,.6f);check(!tiles.isEmpty()&&tiles.size()<30,"detail tile plan unbounded");for(PdfRenderPlan.Tile tile:tiles)check(tile.width<=512&&tile.height<=512&&tile.pageLeft()>=0&&tile.pageRight()<=1,"detail tile outside page");check(PdfRenderPlan.renderWidth(1600,1500)==0&&PdfRenderPlan.renderWidth(1000,1800)>=2048,"detail scale selection");
        InkPage.Stroke oldStroke=new InkPage.Stroke(0xff000000,.01f,new float[]{.1f,.1f,.9f,.9f}),newStroke=new InkPage.Stroke(0xff0000ff,.01f,new float[]{.2f,.2f,.8f,.8f});String key="doc-1-8";
        InkStore.save(root,key,Collections.singletonList(oldStroke));InkStore.prepareClear(key,Collections.singletonList(oldStroke));InkStore.pending.put(key,Collections.emptyList());InkStore.save(root,key,Collections.emptyList());check(InkStore.hasClearRecovery(root,key),"clear recovery missing");
        InkStore.pending.put(key,Collections.singletonList(newStroke));InkStore.save(root,key,Collections.singletonList(newStroke));List<InkPage.Stroke> recovery=InkStore.loadClearRecovery(root,key);check(InkPage.sameContent(recovery,Collections.singletonList(oldStroke)),"clear recovery overwritten by new ink");
        ArrayList<InkPage.Stroke> merged=new ArrayList<>(recovery);merged.add(newStroke);long recoveryRevision=InkStore.stage(key,merged);check(InkStore.consumeClearRecovery(root,key,recoveryRevision),"clear recovery was superseded");check(InkPage.sameContent(InkStore.load(root,key),merged)&&!InkStore.hasClearRecovery(root,key),"clear recovery consume failed");
        System.out.println("ReaderModuleTest passed: metadata/store/source links, revision-safe async load and cross-instance handoff, corrupt rejection, page calibration, bounded detail tiles, durable clear recovery and post-clear merge.");
    }
}
